def or_merge(t, b):
    result = []
    for i in range(len(t)):
        row = []
        for j in range(len(t[0])):
            if t[i][j] == 8 or b[i][j] == 8:
                row.append(8)
            else:
                row.append(9)
        result.append(row)
    return result

